const header=document.querySelector('.site-header');const menu=document.querySelector('.menu');if(menu){menu.addEventListener('click',()=>{const open=header.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});}document.querySelectorAll('.lead-form').forEach(form=>{const params=new URLSearchParams(location.search);const place=params.get('plaats');if(place&&form.elements.plaats)form.elements.plaats.value=place.slice(0,100);const service=params.get('dienst');const option=Array.from(form.querySelectorAll('option[data-service]')).find(o=>o.dataset.service===service);if(option){option.selected=true;option.closest('details')?.setAttribute('open','');}const files=form.querySelector('input[type=file]');if(files)files.addEventListener('change',()=>{const selected=Array.from(files.files);files.setCustomValidity(selected.length>5?'Kies maximaal 5 bestanden.':selected.some(f=>f.size>8*1024*1024)?'Een bestand is groter dan 8 MB.':selected.reduce((n,f)=>n+f.size,0)>20*1024*1024?'De bestanden zijn samen groter dan 20 MB.':'');});const button=form.querySelector('.whatsapp-submit');if(!button)return;button.addEventListener('click',()=>{if(!form.reportValidity())return;if(form.elements.website?.value)return;const data=new FormData(form);const lines=['Goedendag, ik wil via de website een aanvraag indienen.'];const labels={formulier:'Type aanvraag',voornaam:'Voornaam',achternaam:'Achternaam',naam:'Naam',bedrijf:'Bedrijf',email:'E-mail',telefoon:'Telefoon',postcode:'Postcode',huisnummer:'Huisnummer',toevoeging:'Toevoeging',plaats:'Plaats',klanttype:'Type klant','werkzaamheden[]':'Werkzaamheden',omschrijving:'Omschrijving',planning:'Planning',contactvoorkeur:'Contactvoorkeur',storing:'Type storing',gewenste_tijd:'Gewenst moment'};for(const [key,value] of data.entries()){if(key==='website'||value instanceof File||!String(value).trim())continue;lines.push((labels[key]||key)+': '+value);}lines.push('Foto’s of documenten stuur ik eventueel in dit WhatsApp-gesprek.');form.querySelector('.form-status').textContent='WhatsApp wordt geopend. Controleer het bericht en druk daar op verzenden.';window.open('https://wa.me/31613271261?text='+encodeURIComponent(lines.join(String.fromCharCode(10))),'_blank','noopener');});});